INSERT INTO articles VALUES(3,'飛行機の予定','user input','飛行機に乗る予定です。','{"title": "飛行機の予定", "source": "user input", "sentences": [{"id": "s1", "ja": "飛行機に乗る予定です。", "zh": "我预定要乘坐飞机。", "tokens": [{"surface": "飛行機", "dict_form": "飛行機", "reading": "ひこうき", "pos": "noun", "meaning_zh": "飞机", "start": 0, "end": 3}, {"surface": "乗る", "dict_form": "乗る", "reading": "のる", "pos": "verb", "meaning_zh": "乘坐", "start": 4, "end": 6}, {"surface": "予定", "dict_form": "予定", "reading": "よてい", "pos": "noun", "meaning_zh": "预定，计划", "start": 6, "end": 8}], "grammar": [{"canonical_id": "g_ru_koto_ni_naru", "display_form": "Verb る 予定です", "meaning_zh": "预定做～", "explanation": "「飛行機に乗る予定です」表示计划或预定乘坐飞机，使用「Verbる＋予定です」结构表达既定计划。"}]}]}','2026-06-02 06:56:34');
INSERT INTO articles VALUES(4,'猫が好きです','user input','猫が好きです。','{"title":"猫が好きです","source":"user input","sentences":[{"id":"s1","ja":"猫が好きです。","zh":"我喜欢猫。","tokens":[{"surface":"猫","dict_form":"猫","reading":"ねこ","pos":"noun","meaning_zh":"猫","start":0,"end":1},{"surface":"好き","dict_form":"好き","reading":"すき","pos":"na_adjective","meaning_zh":"喜欢","start":2,"end":4}],"grammar":[{"canonical_id":"g_a_wa_b_ga","display_form":"A は B が〜","meaning_zh":"表示对某事物的感受或特征","explanation":"此句用「が」标记喜好的对象「猫」，表达「喜欢猫」的意思"}]}]}','2026-06-03 07:36:55');
INSERT INTO articles VALUES(5,'台風6号のニュース','user input',replace('台風6号のニュースです。\n気象庁によると、台風は沖縄の近くを北に進んでいます。\n沖縄や奄美で、とても強い風が吹いています。\n走っているトラックが倒れるくらい強い風が吹くかもしれません。\nとてもたくさん雨が降って、山が崩れたり、川の水があふれたりする心配もあります。\n台風は、2日と3日は、西日本と東日本の近くに来そうです。\n台風の新しい情報を調べて、台風が近くに来る前に準備してください。\n飛行機や新幹線などに乗る予定の人は、情報を調べましょう。','\n',char(10)),'{"title":"台風6号のニュース","source":"user input","sentences":[{"id":"s1","ja":"台風6号のニュースです。","zh":"这是关于台风6号的新闻。","tokens":[{"surface":"台風","dict_form":"台風","reading":"たいふう","pos":"noun","meaning_zh":"台风","start":0,"end":2},{"surface":"6号","dict_form":"6号","reading":"ろくごう","pos":"noun","meaning_zh":"6号","start":2,"end":4},{"surface":"ニュース","dict_form":"ニュース","reading":"にゅーす","pos":"noun","meaning_zh":"新闻","start":5,"end":9}],"grammar":[{"canonical_id":"g_noun_wa","display_form":"Noun は～","meaning_zh":"表示主题","explanation":"「台風6号のニュース」作为句子的主题，用です结句表示「这是……」"}]},{"id":"s2","ja":"気象庁によると、台風は沖縄の近くを北に進んでいます。","zh":"据气象厅消息，台风正在冲绳附近向北推进。","tokens":[{"surface":"気象庁","dict_form":"気象庁","reading":"きしょうちょう","pos":"noun","meaning_zh":"气象厅","start":0,"end":3},{"surface":"台風","dict_form":"台風","reading":"たいふう","pos":"noun","meaning_zh":"台风","start":8,"end":10},{"surface":"沖縄","dict_form":"沖縄","reading":"おきなわ","pos":"noun","meaning_zh":"冲绳","start":11,"end":13},{"surface":"近く","dict_form":"近く","reading":"ちかく","pos":"noun","meaning_zh":"附近","start":14,"end":16},{"surface":"北","dict_form":"北","reading":"きた","pos":"noun","meaning_zh":"北方","start":17,"end":18},{"surface":"進んで","dict_form":"進む","reading":"すすんで","pos":"verb","meaning_zh":"前进","start":19,"end":22}],"grammar":[{"canonical_id":"g_ni_yoreba","display_form":"～によれば","meaning_zh":"根据……","explanation":"「気象庁によると」表示信息来源，意为「根据气象厅」"},{"canonical_id":"g_verb_te_imasu","display_form":"Verb て います","meaning_zh":"正在……","explanation":"「進んでいます」表示台风正在持续向北移动的动作"}]},{"id":"s3","ja":"沖縄や奄美で、とても強い風が吹いています。","zh":"冲绳和奄美正在刮着非常强劲的风。","tokens":[{"surface":"沖縄","dict_form":"沖縄","reading":"おきなわ","pos":"noun","meaning_zh":"冲绳","start":0,"end":2},{"surface":"奄美","dict_form":"奄美","reading":"あまみ","pos":"noun","meaning_zh":"奄美","start":3,"end":5},{"surface":"強い","dict_form":"強い","reading":"つよい","pos":"i_adjective","meaning_zh":"强烈的","start":10,"end":12},{"surface":"風","dict_form":"風","reading":"かぜ","pos":"noun","meaning_zh":"风","start":12,"end":13},{"surface":"吹いて","dict_form":"吹く","reading":"ふいて","pos":"verb","meaning_zh":"吹","start":14,"end":17}],"grammar":[{"canonical_id":"g_noun_ya_noun_nado","display_form":"Noun や Noun など～","meaning_zh":"……和……等","explanation":"「沖縄や奄美で」用や列举两个地点，表示非穷举的并列"},{"canonical_id":"g_verb_te_imasu","display_form":"Verb て います","meaning_zh":"正在……","explanation":"「吹いています」表示强风正在持续吹的状态"}]},{"id":"s4","ja":"走っているトラックが倒れるくらい強い風が吹くかもしれません。","zh":"可能会刮起强到能把行驶中的卡车吹倒的风。","tokens":[{"surface":"走って","dict_form":"走る","reading":"はしって","pos":"verb","meaning_zh":"行驶","start":0,"end":3},{"surface":"トラック","dict_form":"トラック","reading":"とらっく","pos":"noun","meaning_zh":"卡车","start":5,"end":9},{"surface":"倒れる","dict_form":"倒れる","reading":"たおれる","pos":"verb","meaning_zh":"倒下","start":10,"end":13},{"surface":"強い","dict_form":"強い","reading":"つよい","pos":"i_adjective","meaning_zh":"强烈的","start":16,"end":18},{"surface":"風","dict_form":"風","reading":"かぜ","pos":"noun","meaning_zh":"风","start":18,"end":19},{"surface":"吹く","dict_form":"吹く","reading":"ふく","pos":"verb","meaning_zh":"吹","start":20,"end":22}],"grammar":[{"canonical_id":"g_verb_te_imasu","display_form":"Verb て います","meaning_zh":"正在……","explanation":"「走っている」修饰トラック，表示「正在行驶的卡车」"},{"canonical_id":"g_kurai","display_form":"～くらい～","meaning_zh":"到……程度","explanation":"「倒れるくらい強い風」表示风强到足以把卡车吹倒的程度"},{"canonical_id":"g_kamoshirenai","display_form":"～かもしれない","meaning_zh":"也许……，可能……","explanation":"「吹くかもしれません」表示有可能刮起这样的强风，带有不确定性"}]},{"id":"s5","ja":"とてもたくさん雨が降って、山が崩れたり、川の水があふれたりする心配もあります。","zh":"雨量非常大，也有山体滑坡、河水泛滥的担忧。","tokens":[{"surface":"雨","dict_form":"雨","reading":"あめ","pos":"noun","meaning_zh":"雨","start":7,"end":8},{"surface":"降って","dict_form":"降る","reading":"ふって","pos":"verb","meaning_zh":"下（雨）","start":9,"end":12},{"surface":"山","dict_form":"山","reading":"やま","pos":"noun","meaning_zh":"山","start":13,"end":14},{"surface":"崩れ","dict_form":"崩れる","reading":"くずれ","pos":"verb","meaning_zh":"崩塌","start":15,"end":17},{"surface":"川","dict_form":"川","reading":"かわ","pos":"noun","meaning_zh":"河流","start":20,"end":21},{"surface":"水","dict_form":"水","reading":"みず","pos":"noun","meaning_zh":"水","start":22,"end":23},{"surface":"あふれ","dict_form":"あふれる","reading":"あふれ","pos":"verb","meaning_zh":"泛滥","start":24,"end":27},{"surface":"心配","dict_form":"心配","reading":"しんぱい","pos":"noun","meaning_zh":"担忧","start":31,"end":33}],"grammar":[{"canonical_id":"g_tari_tari_shimasu","display_form":"～たり、～たり します","meaning_zh":"……啦……啦（列举动作）","explanation":"「崩れたり、あふれたりする」列举山体崩塌和河水泛滥两种可能的灾害情况"},{"canonical_id":"g_arimasu","display_form":"～あります","meaning_zh":"有……","explanation":"「心配もあります」表示存在这样的担忧"}]},{"id":"s6","ja":"台風は、2日と3日は、西日本と東日本の近くに来そうです。","zh":"台风在2日和3日可能会靠近西日本和东日本。","tokens":[{"surface":"台風","dict_form":"台風","reading":"たいふう","pos":"noun","meaning_zh":"台风","start":0,"end":2},{"surface":"2日","dict_form":"2日","reading":"ふつか","pos":"noun","meaning_zh":"2日","start":4,"end":6},{"surface":"3日","dict_form":"3日","reading":"みっか","pos":"noun","meaning_zh":"3日","start":7,"end":9},{"surface":"西日本","dict_form":"西日本","reading":"にしにほん","pos":"noun","meaning_zh":"西日本","start":11,"end":14},{"surface":"東日本","dict_form":"東日本","reading":"ひがしにほん","pos":"noun","meaning_zh":"东日本","start":15,"end":18},{"surface":"近く","dict_form":"近く","reading":"ちかく","pos":"noun","meaning_zh":"附近","start":19,"end":21},{"surface":"来","dict_form":"来る","reading":"き","pos":"verb","meaning_zh":"来","start":22,"end":23}],"grammar":[{"canonical_id":"g_noun_to","display_form":"Noun と～","meaning_zh":"……和……","explanation":"「2日と3日」「西日本と東日本」用と连接并列的名词"},{"canonical_id":"g_sou_da","display_form":"～そうだ","meaning_zh":"好像……，看来……","explanation":"「来そうです」表示根据现有情况推测台风将会靠近"}]},{"id":"s7","ja":"台風の新しい情報を調べて、台風が近くに来る前に準備してください。","zh":"请查看台风的最新信息，在台风靠近之前做好准备。","tokens":[{"surface":"台風","dict_form":"台風","reading":"たいふう","pos":"noun","meaning_zh":"台风","start":0,"end":2},{"surface":"新しい","dict_form":"新しい","reading":"あたらしい","pos":"i_adjective","meaning_zh":"最新的","start":3,"end":6},{"surface":"情報","dict_form":"情報","reading":"じょうほう","pos":"noun","meaning_zh":"信息","start":6,"end":8},{"surface":"調べて","dict_form":"調べる","reading":"しらべて","pos":"verb","meaning_zh":"查阅","start":9,"end":12},{"surface":"近く","dict_form":"近く","reading":"ちかく","pos":"noun","meaning_zh":"附近","start":16,"end":18},{"surface":"来る","dict_form":"来る","reading":"くる","pos":"verb","meaning_zh":"来","start":19,"end":21},{"surface":"準備","dict_form":"準備","reading":"じゅんび","pos":"noun","meaning_zh":"准备","start":23,"end":25}],"grammar":[{"canonical_id":"g_verb_te","display_form":"Verb て～","meaning_zh":"……之后（连接动作）","explanation":"「調べて」用て形连接两个动作，先查信息再做准备"},{"canonical_id":"g_ru_mae_ni","display_form":"Verb る 前に","meaning_zh":"在……之前","explanation":"「来る前に」表示在台风靠近之前应该完成准备"},{"canonical_id":"g_verb_te_kudasai","display_form":"Verb て ください","meaning_zh":"请……","explanation":"「準備してください」是礼貌的请求，要求读者做好准备"}]},{"id":"s8","ja":"飛行機や新幹線などに乗る予定の人は、情報を調べましょう。","zh":"有乘坐飞机或新干线等交通工具计划的人，请查阅相关信息。","tokens":[{"surface":"飛行機","dict_form":"飛行機","reading":"ひこうき","pos":"noun","meaning_zh":"飞机","start":0,"end":3},{"surface":"新幹線","dict_form":"新幹線","reading":"しんかんせん","pos":"noun","meaning_zh":"新干线","start":4,"end":7},{"surface":"乗る","dict_form":"乗る","reading":"のる","pos":"verb","meaning_zh":"乘坐","start":10,"end":12},{"surface":"予定","dict_form":"予定","reading":"よてい","pos":"noun","meaning_zh":"计划","start":12,"end":14},{"surface":"人","dict_form":"人","reading":"ひと","pos":"noun","meaning_zh":"人","start":15,"end":16},{"surface":"情報","dict_form":"情報","reading":"じょうほう","pos":"noun","meaning_zh":"信息","start":18,"end":20},{"surface":"調べ","dict_form":"調べる","reading":"しらべ","pos":"verb","meaning_zh":"查阅","start":21,"end":23}],"grammar":[{"canonical_id":"g_noun_ya_noun_nado","display_form":"Noun や Noun など～","meaning_zh":"……和……等","explanation":"「飛行機や新幹線など」用や和など列举交通工具，表示非穷举"},{"canonical_id":"g_tsumori","display_form":"Verb つもり","meaning_zh":"打算……","explanation":"「乗る予定の人」中予定与つもり类似，表示有乘坐计划的人"},{"canonical_id":"g_mashou","display_form":"Verb ましょう","meaning_zh":"让我们……吧","explanation":"「調べましょう」是劝诱形，建议有出行计划的人主动查阅信息"}]}]}','2026-06-03 07:37:58');
INSERT INTO articles VALUES(6,'緊急・災害時用軽量ページの案内','user input',replace('現在、緊急・災害時用に軽量化したページを表示しています。\nバッテリーの節約にもなります。','\n',char(10)),'{"title":"緊急・災害時用軽量ページの案内","source":"user input","sentences":[{"id":"s1","ja":"現在、緊急・災害時用に軽量化したページを表示しています。","zh":"目前正在显示为紧急・灾害时准备的轻量化页面。","tokens":[{"surface":"現在","dict_form":"現在","reading":"げんざい","pos":"noun","meaning_zh":"现在、目前","start":0,"end":2},{"surface":"緊急","dict_form":"緊急","reading":"きんきゅう","pos":"noun","meaning_zh":"紧急","start":3,"end":5},{"surface":"災害","dict_form":"災害","reading":"さいがい","pos":"noun","meaning_zh":"灾害","start":6,"end":8},{"surface":"用","dict_form":"用","reading":"よう","pos":"noun","meaning_zh":"用途、专用","start":9,"end":10},{"surface":"軽量化","dict_form":"軽量化","reading":"けいりょうか","pos":"noun","meaning_zh":"轻量化","start":11,"end":14},{"surface":"ページ","dict_form":"ページ","reading":"ぺーじ","pos":"noun","meaning_zh":"页面","start":16,"end":19},{"surface":"表示","dict_form":"表示","reading":"ひょうじ","pos":"noun","meaning_zh":"显示","start":20,"end":22},{"surface":"し","dict_form":"する","reading":"し","pos":"verb","meaning_zh":"做","start":22,"end":23}],"grammar":[{"canonical_id":"g_verb_te_imasu","display_form":"Verb て います","meaning_zh":"正在……","explanation":"「表示しています」表示当前正在进行显示这一动作的持续状态。"},{"canonical_id":"g_tame_ni","display_form":"Verb ために","meaning_zh":"为了……","explanation":"「緊急・災害時用に」表示为紧急及灾害时的用途而准备。"}]},{"id":"s2","ja":"バッテリーの節約にもなります。","zh":"这样也有助于节省电池电量。","tokens":[{"surface":"バッテリー","dict_form":"バッテリー","reading":"ばってりー","pos":"noun","meaning_zh":"电池","start":0,"end":5},{"surface":"節約","dict_form":"節約","reading":"せつやく","pos":"noun","meaning_zh":"节约、节省","start":6,"end":8},{"surface":"なり","dict_form":"なる","reading":"なり","pos":"verb","meaning_zh":"成为、有助于","start":10,"end":12}],"grammar":[{"canonical_id":"g_noun_ni_narimasu","display_form":"Noun に なります","meaning_zh":"变成……、有助于……","explanation":"「節約にもなります」表示同时也能起到节省电池的效果。"},{"canonical_id":"g_noun_mo","display_form":"Noun も〜","meaning_zh":"也……","explanation":"「も」表示除了其他好处之外，节省电池也是其中之一。"}]}]}','2026-06-03 07:44:22');
INSERT INTO articles VALUES(7,'アメリカとイランの戦いと日本の経済対策','user input',replace('アメリカなどとイランの戦いが続いて、いろいろな物の値段が上がっています。\n\n国会は、5日、国の予算を3兆1000億円ぐらい増やすことを決めました。\n\n政府は、このお金を使って、経済が悪くならないようにしたいと考えています。電気代やガス代などを安くできるように準備しています。\n\n政府は、この予算のために、「国債」を出してお金を借りる予定です。','\n',char(10)),'{"title":"アメリカとイランの戦いと日本の経済対策","source":"user input","sentences":[{"id":"s1","ja":"アメリカなどとイランの戦いが続いて、いろいろな物の値段が上がっています。","zh":"美国等国与伊朗的战争持续，各种物品的价格不断上涨。","tokens":[{"surface":"アメリカ","dict_form":"アメリカ","reading":"あめりか","pos":"noun","meaning_zh":"美国","start":0,"end":4},{"surface":"イラン","dict_form":"イラン","reading":"いらん","pos":"noun","meaning_zh":"伊朗","start":7,"end":10},{"surface":"戦い","dict_form":"戦い","reading":"たたかい","pos":"noun","meaning_zh":"战争、战斗","start":11,"end":13},{"surface":"続い","dict_form":"続く","reading":"つづく","pos":"verb","meaning_zh":"持续","start":14,"end":16},{"surface":"いろいろ","dict_form":"いろいろ","reading":"いろいろ","pos":"adverb","meaning_zh":"各种各样","start":18,"end":22},{"surface":"物","dict_form":"物","reading":"もの","pos":"noun","meaning_zh":"物品","start":23,"end":24},{"surface":"値段","dict_form":"値段","reading":"ねだん","pos":"noun","meaning_zh":"价格","start":25,"end":27},{"surface":"上がっ","dict_form":"上がる","reading":"あがる","pos":"verb","meaning_zh":"上涨","start":28,"end":31}],"grammar":[{"canonical_id":"g_noun_ya_noun_nado","display_form":"Noun など","meaning_zh":"等、之类","explanation":"「アメリカなど」表示以美国为代表的多个国家，列举不完全。"},{"canonical_id":"g_verb_te","display_form":"Verb て","meaning_zh":"……之后、并且","explanation":"「続いて」用て形连接两个动作，表示战争持续，进而导致物价上涨。"},{"canonical_id":"g_verb_te_imasu","display_form":"Verb ています","meaning_zh":"正在……、持续……","explanation":"「上がっています」表示价格持续上涨的状态。"}]},{"id":"s2","ja":"国会は、5日、国の予算を3兆1000億円ぐらい増やすことを決めました。","zh":"国会于5日决定将国家预算增加约3兆1000亿日元。","tokens":[{"surface":"国会","dict_form":"国会","reading":"こっかい","pos":"noun","meaning_zh":"国会","start":0,"end":2},{"surface":"5日","dict_form":"5日","reading":"いつか","pos":"noun","meaning_zh":"5号","start":4,"end":6},{"surface":"国","dict_form":"国","reading":"くに","pos":"noun","meaning_zh":"国家","start":7,"end":8},{"surface":"予算","dict_form":"予算","reading":"よさん","pos":"noun","meaning_zh":"预算","start":9,"end":11},{"surface":"3兆1000億円","dict_form":"3兆1000億円","reading":"さんちょういっせんおくえん","pos":"noun","meaning_zh":"3兆1000亿日元","start":12,"end":20},{"surface":"増やす","dict_form":"増やす","reading":"ふやす","pos":"verb","meaning_zh":"增加","start":23,"end":26},{"surface":"決め","dict_form":"決める","reading":"きめる","pos":"verb","meaning_zh":"决定","start":29,"end":31}],"grammar":[{"canonical_id":"g_noun_gurai","display_form":"Noun ぐらい","meaning_zh":"大约、左右","explanation":"「3兆1000億円ぐらい」表示金额的大概数字。"},{"canonical_id":"g_ru_koto","display_form":"Verb ること","meaning_zh":"做……这件事","explanation":"「増やすことを決めました」将动词名词化，作为「決める」的宾语。"}]},{"id":"s3","ja":"政府は、このお金を使って、経済が悪くならないようにしたいと考えています。","zh":"政府希望利用这笔钱，采取措施使经济不至于恶化。","tokens":[{"surface":"政府","dict_form":"政府","reading":"せいふ","pos":"noun","meaning_zh":"政府","start":0,"end":2},{"surface":"お金","dict_form":"お金","reading":"おかね","pos":"noun","meaning_zh":"钱","start":6,"end":8},{"surface":"使っ","dict_form":"使う","reading":"つかう","pos":"verb","meaning_zh":"使用","start":9,"end":11},{"surface":"経済","dict_form":"経済","reading":"けいざい","pos":"noun","meaning_zh":"经济","start":13,"end":15},{"surface":"悪く","dict_form":"悪い","reading":"わるい","pos":"i_adjective","meaning_zh":"变差","start":16,"end":18},{"surface":"なら","dict_form":"なる","reading":"なる","pos":"verb","meaning_zh":"变成","start":18,"end":20},{"surface":"し","dict_form":"する","reading":"する","pos":"verb","meaning_zh":"做","start":25,"end":26},{"surface":"考え","dict_form":"考える","reading":"かんがえる","pos":"verb","meaning_zh":"考虑、认为","start":29,"end":31}],"grammar":[{"canonical_id":"g_verb_te","display_form":"Verb て","meaning_zh":"通过……","explanation":"「使って」用て形表示手段，即通过使用这笔钱来实现目的。"},{"canonical_id":"g_i_adjective_ku_verb","display_form":"い-Adjective く + Verb","meaning_zh":"变得……","explanation":"「悪くならない」中「悪く」是「悪い」的副词形，修饰「なる」。"},{"canonical_id":"g_you_ni_n4","display_form":"Verb ようにする","meaning_zh":"设法使……、努力做到……","explanation":"「悪くならないようにしたい」表示政府希望采取措施使经济不恶化。"},{"canonical_id":"g_to_omou","display_form":"～と考えています","meaning_zh":"认为……、考虑……","explanation":"「したいと考えています」表示政府的想法和意图。"}]},{"id":"s4","ja":"電気代やガス代などを安くできるように準備しています。","zh":"正在为能够降低电费和燃气费等做准备。","tokens":[{"surface":"電気代","dict_form":"電気代","reading":"でんきだい","pos":"noun","meaning_zh":"电费","start":0,"end":3},{"surface":"ガス代","dict_form":"ガス代","reading":"がすだい","pos":"noun","meaning_zh":"燃气费","start":4,"end":7},{"surface":"安く","dict_form":"安い","reading":"やすい","pos":"i_adjective","meaning_zh":"便宜","start":10,"end":12},{"surface":"でき","dict_form":"できる","reading":"できる","pos":"verb","meaning_zh":"能够","start":12,"end":14},{"surface":"準備","dict_form":"準備","reading":"じゅんび","pos":"noun","meaning_zh":"准备","start":18,"end":20}],"grammar":[{"canonical_id":"g_noun_ya_noun_nado","display_form":"Noun や Noun など","meaning_zh":"……和……等","explanation":"「電気代やガス代など」列举电费、燃气费等例子，并非穷举。"},{"canonical_id":"g_i_adjective_ku_verb","display_form":"い-Adjective く + Verb","meaning_zh":"变得便宜","explanation":"「安くできる」中「安く」是「安い」的副词形，修饰「できる」，表示使之变便宜。"},{"canonical_id":"g_you_ni_n4","display_form":"Verb ように","meaning_zh":"为了能够……","explanation":"「安くできるように準備しています」表示为了实现降低费用的目标而做准备。"},{"canonical_id":"g_verb_te_imasu","display_form":"Verb ています","meaning_zh":"正在……","explanation":"「準備しています」表示目前正在进行准备的状态。"}]},{"id":"s5","ja":"政府は、この予算のために、「国債」を出してお金を借りる予定です。","zh":"政府计划为此预算发行「国债」来借款。","tokens":[{"surface":"政府","dict_form":"政府","reading":"せいふ","pos":"noun","meaning_zh":"政府","start":0,"end":2},{"surface":"予算","dict_form":"予算","reading":"よさん","pos":"noun","meaning_zh":"预算","start":6,"end":8},{"surface":"国債","dict_form":"国債","reading":"こくさい","pos":"noun","meaning_zh":"国债","start":14,"end":16},{"surface":"出し","dict_form":"出す","reading":"だす","pos":"verb","meaning_zh":"发行、拿出","start":18,"end":20},{"surface":"お金","dict_form":"お金","reading":"おかね","pos":"noun","meaning_zh":"钱","start":21,"end":23},{"surface":"借りる","dict_form":"借りる","reading":"かりる","pos":"verb","meaning_zh":"借","start":24,"end":27},{"surface":"予定","dict_form":"予定","reading":"よてい","pos":"noun","meaning_zh":"预定、计划","start":27,"end":29}],"grammar":[{"canonical_id":"g_tame_ni","display_form":"Noun のために","meaning_zh":"为了……","explanation":"「この予算のために」表示发行国债的目的是为了筹措预算资金。"},{"canonical_id":"g_verb_te","display_form":"Verb て","meaning_zh":"……之后、通过……","explanation":"「出して」用て形连接两个动作，表示先发行国债，再借钱。"},{"canonical_id":"g_tsumori","display_form":"Verb 予定です","meaning_zh":"预计……、计划……","explanation":"「借りる予定です」表示政府有借款的计划安排。"}]}]}','2026-06-05 15:56:12');
